    public static int sumConsecutiveNumbers(List<Integer> numbers) {
        if (numbers.isEmpty()) {
            return 0;
        }

        return IntStream.range(0, numbers.size() - 1)
                .map(i -> numbers.get(i) + numbers.get(i + 1))
                .sum() - numbers.stream().mapToInt(Integer::intValue).sum();
